import { isValidEmail } from './clean-code';

describe('isValidEmail', () => {
  it('returns false for emails with spaces', () => {
    expect(isValidEmail('user @example.com')).toBe(false);
    expect(isValidEmail(' user@example.com')).toBe(false);
  });

  it('returns false for emails without @ symbol', () => {
    expect(isValidEmail('userexample.com')).toBe(false);
  });

  it('returns false for emails without domain extension', () => {
    expect(isValidEmail('user@example')).toBe(false);
  });

  it('returns false for empty string', () => {
    expect(isValidEmail('')).toBe(false);
  });

  it('returns true for valid email format', () => {
    expect(isValidEmail('user@example.com')).toBe(true);
    expect(isValidEmail('test.user+tag@sub.example.co.uk')).toBe(true);
  });
});

import { sanitizeInput } from './clean-code';

describe('sanitizeInput', () => {
  it('escapes less-than and greater-than to prevent tag injection', () => {
    expect(sanitizeInput('<script>alert("XSS")</script>'))
      .toBe('&lt;script&gt;alert(&quot;XSS&quot;)&lt;/script&gt;');
  });

  it('escapes single and double quotes to prevent attribute injection', () => {
    expect(sanitizeInput('" onload="alert(1)'))
      .toBe('&quot; onload=&quot;alert(1)');
    expect(sanitizeInput("' onclick='alert(1)"))
      .toBe('&#039; onclick=&#039;alert(1)');
  });

  it('handles multiple special characters in sequence', () => {
    expect(sanitizeInput('<><""\'\'>'))
      .toBe('&lt;&gt;&lt;&quot;&quot;&#039;&#039;&gt;');
  });

  it('returns empty string when input is empty', () => {
    expect(sanitizeInput('')).toBe('');
  });

  it('preserves safe characters and spaces', () => {
    expect(sanitizeInput('John Doe 123'))
      .toBe('John Doe 123');
  });
});

