describe('createUser - happy path', () => {
  beforeEach(() => {
    jest.useFakeTimers();
    jest.setSystemTime(new Date('2024-01-15T10:00:00Z'));
  });

  afterEach(() => {
    jest.useRealTimers();
  });

  it('creates user with sanitized name and lowercase email', async () => {
    const input = { email: 'User@Example.COM', name: 'John <script>alert(1)</script>' };
    const user = await createUser(input);

    expect(user.email).toBe('user@example.com');
    expect(user.name).toBe('John &lt;script&gt;alert(1)&lt;/script&gt;');
    expect(user.id).toMatch(/^user_\d+_[a-z0-9]{7}$/);
    expect(user.createdAt).toEqual(new Date('2024-01-15T10:00:00Z'));
  });

  it('generates unique IDs for different users', async () => {
    const user1 = await createUser({ email: 'user1@example.com', name: 'User One' });
    const user2 = await createUser({ email: 'user2@example.com', name: 'User Two' });

    expect(user1.id).not.toBe(user2.id);
  });
});

