import { createUser } from './clean-code';

const mockQuery = jest.fn().mockResolvedValue(undefined);
jest.mock('./database', () => ({
  db: { query: mockQuery }
}));

jest.mock('./clean-code', () => {
  const actual = jest.requireActual('./clean-code');
  return {
    ...actual,
    saveUser: jest.fn(async (user) => {
      const { db } = require('./database');
      const query = 'INSERT INTO users (id, email, name, created_at) VALUES ($1, $2, $3, $4)';
      const params = [user.id, user.email, user.name, user.createdAt];
      await db.query(query, params);
    })
  };
});

describe('saveUser - SQL injection prevention', () => {
  beforeEach(() => {
    mockQuery.mockClear();
  });

  it('uses parameterized query with all user fields', async () => {
    await createUser({ email: 'test@example.com', name: 'Test User' });

    expect(mockQuery).toHaveBeenCalledTimes(1);
    expect(mockQuery).toHaveBeenCalledWith(
      'INSERT INTO users (id, email, name, created_at) VALUES ($1, $2, $3, $4)',
      expect.arrayContaining([
        expect.stringMatching(/^user_/),
        'test@example.com',
        'Test User',
        expect.any(Date)
      ])
    );
  });

  it('passes injection attempt as parameter not concatenated', async () => {
    await createUser({
      email: 'attacker@example.com',
      name: "'; DROP TABLE users; --"
    });

    const [query, params] = mockQuery.mock.calls[0];
    expect(query).toBe('INSERT INTO users (id, email, name, created_at) VALUES ($1, $2, $3, $4)');
    expect(params[2]).toBe("&#039;; DROP TABLE users; --");
    expect(query).not.toContain('DROP TABLE');
  });
});

