export function sanitizeInput(input: string): string {
  const escapeMap = {
    '<': '&lt;',
    '>': '&gt;',
    '"': '&quot;',
    "'": '&#039;'
  } as const;

  return input.replace(/[<>"']/g, (char) => escapeMap[char as keyof typeof escapeMap]);
}

